@@ -8705,6 +8705,33 @@ export function createTypeChecker(host: TypeCheckerHost): TypeChecker {
             return result ?? factory.createKeywordTypeNode(SyntaxKind.AnyKeyword);
         }
 
+        /**
+         * The syntactic node builder can reproduce the type of a declaration from the declaration itself. For declarations with a type
+         * annotation, that is verified against the type being serialized (see `canReuseTypeNodeAnnotation`), but for declarations whose
+         * type is inferred (from an initializer, an assertion, the expressions returned from a getter, etc.) it is not, so the result is
+         * only meaningful if `type` is the type of the declaration itself. Symbols that stand in for a declaration (properties of mapped
+         * types, instantiated types, spread objects, etc.) share the declarations of the symbol they originate from, but can have a
+         * different type, in which case nothing may be reused from that declaration.
+         */
+        function isTypeOfDeclaration(declaration: Declaration, symbol: Symbol, type: Type) {
+            if (hasTypeAnnotation(declaration)) {
+                return true;
+            }
+            const declarationSymbol = declaration.symbol && getSymbolOfDeclaration(declaration);
+            if (!declarationSymbol || declarationSymbol === symbol) {
+                return true;
+            }
+            return type === getTypeOfSymbol(declarationSymbol) || type === getNonMissingTypeOfSymbol(declarationSymbol);
+        }
+
+        function hasTypeAnnotation(declaration: Declaration) {
+            if (isAccessor(declaration)) {
+                const { getAccessor, setAccessor } = getAllAccessorDeclarationsForDeclaration(declaration);
+                return !!(getAccessor && getEffectiveReturnTypeNode(getAccessor) || setAccessor && getEffectiveSetAccessorTypeAnnotationNode(setAccessor));
+            }
+            return !!getEffectiveTypeAnnotationNode(declaration);
+        }
+
         function typeNodeIsEquivalentToType(annotatedDeclaration: Node | undefined, type: Type, typeFromTypeNode: Type) {
             if (typeFromTypeNode === type) {
