+// @strict: true
+// @noEmit: true
+
+// Properties of mapped types (and of other types derived from an object type) share the declarations of the
+// properties they originate from, but they don't necessarily have the same type as those declarations.
+// When printing such a type we should print the type of the property, not the type of an assertion in its declaration.
+
+type Wrapper<T> = {
+    _type: T;
+};
+
+declare function stringWrapper(): Wrapper<string>;
+
+declare function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T>;
+
+const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">,
+});
+
+type Unwrap<T extends Wrapper<any>> = T["_type"] extends Record<string, Wrapper<any>> ? { [Key in keyof T["_type"]]: Unwrap<T["_type"][Key]>; }
+    : T["_type"];
+
+type Test = Unwrap<typeof value>;
+
+declare const test: Test;
+const testError: number = test; // expected: `{ prop1: "hello"; }`
+
+class Box {
+    a = stringWrapper() as Wrapper<"hello">;
+    b = <Wrapper<"hello">> stringWrapper();
+    get c() {
+        return stringWrapper() as Wrapper<"hello">;
+    }
+}
+
+declare const mappedBox: { [K in keyof Box]: 1; };
+const mappedBoxError: number = mappedBox; // expected: `{ a: 1; b: 1; readonly c: 1; }`
+
+class Literals {
+    a = 1;
+    b = "b";
+}
+
+declare const mappedLiterals: { [K in keyof Literals]: K; };
+const mappedLiteralsError: number = mappedLiterals; // expected: `{ a: "a"; b: "b"; }`
+
+declare const partialLiterals: Partial<Literals>;
+const partialLiteralsError: number = { ...partialLiterals }; // expected: `{ a?: number | undefined; b?: string | undefined; }`
+
+const obj = {
+    a: stringWrapper() as Wrapper<"hello">,
+};
+
+declare const mappedObj: { [K in keyof typeof obj]: K; };
+const mappedObjError: number = mappedObj; // expected: `{ a: "a"; }`
+
+declare const optionalObj: Partial<typeof obj>;
+const optionalObjError: number = { ...optionalObj }; // expected: `{ a?: Wrapper<"hello"> | undefined; }`
+
+namespace ns {
+    export const a = stringWrapper() as Wrapper<"hello">;
+    export let b = stringWrapper() as Wrapper<"hello">;
+}
+
+declare const mappedNs: { [K in keyof typeof ns]: 1; };
+const mappedNsError: number = mappedNs; // expected: `{ readonly a: 1; b: 1; }`
+
+class Generic<T> {
+    a = null! as Wrapper<T>;
+    b = null! as Wrapper<"hello">;
+}
+
+declare const generic: Generic<string>;
+const spread = { ...generic };
+const spreadError: number = spread; // expected: `{ a: Wrapper<string>; b: Wrapper<"hello">; }`
+
+declare const readonlyGeneric: Readonly<Generic<number>>;
+const readonlyGenericError: number = { ...readonlyGeneric }; // expected: `{ a: Wrapper<number>; b: Wrapper<"hello">; }`
+
+declare const readonlyObj: Readonly<typeof obj>;
+const readonlyObjError: number = { ...readonlyObj }; // expected: `{ a: Wrapper<"hello">; }`
